65		}
66		s.subWG.Add(1)
67		s.nextSub++
68		id := s.nextSub
69		set := s.subs[key]
70		if set == nil {
71			set = make(map[uint64]*subscription)
72			s.subs[key] = set
73		}
74		set[id] = sub
75		remove := func() {
76			s.mu.Lock()
77			if set, ok := s.subs[key]; ok {
78				if _, ok := set[id]; ok {
79					delete(set, id)
80					if len(set) == 0 {
81						delete(s.subs, key)
82					}
83					s.mu.Unlock()
84					s.subWG.Done()
85					return
86				}
87			}
88			s.mu.Unlock()
89		}
90		return ch, sub.revoked, sub.deleted, remove
91	}
