333	// Concurrent deletes of one document take effect at most once: exactly one
334	// 200, every other call a 404, and no half-cleaned state survives.
335	func TestDeleteDocumentConcurrentOnce(t *testing.T) {
336		h, _ := newTestHandler(t)
337		registerDevice(t, h, "dev-1")
338		postDocChangeHandler(t, h, "dev-1", "doc")
339	
340		const n = 20
341		var wg sync.WaitGroup
342		start := make(chan struct{})
343		statuses := make([]int, n)
344		for i := 0; i < n; i++ {
345			wg.Add(1)
346			go func(i int) {
347				defer wg.Done()
348				<-start
349				w, _ := doRequest(t, h, http.MethodDelete, "/v1/documents/doc?deviceId=dev-1")
350				statuses[i] = w.Code
351			}(i)
352		}
353		close(start)
354		wg.Wait()
355	
356		var ok, missing int
357		for _, code := range statuses {
358			switch code {
359			case http.StatusOK:
360				ok++
361			case http.StatusNotFound:
362				missing++
363			default:
364				t.Fatalf("unexpected status %d", code)
365			}
366		}
367		if ok != 1 || missing != n-1 {
368			t.Fatalf("want exactly one 200 and %d 404s, got %d and %d", n-1, ok, missing)
369		}
370	
371		// The document is fully gone: a read is an empty unknown document and a
372		// further delete still misses.
373		w, _ := doRequest(t, h, http.MethodGet, "/v1/documents/doc/changes")
374		if strings.TrimSpace(w.Body.String()) != `{"changes":[],"nextCursor":0}` {
375			t.Fatalf("document not fully cleaned: %s", w.Body.String())
376		}
377		w, _ = doRequest(t, h, http.MethodDelete, "/v1/documents/doc?deviceId=dev-1")
378		if w.Code != http.StatusNotFound {
379			t.Fatalf("repeat delete after concurrent cleanup = %d, want 404", w.Code)
380		}
381	}
