389		setupSession(t, srv, "dev-1", "sess-1", "victim", 1)
390		registerDeviceViaHTTP(t, srv, "dev-2")
391		setupSession(t, srv, "dev-2", "sess-2", "other", 0)
392		// Give the victim a CRDT state and the control doc one too.
393		if code := postCRDTOps(t, srv, "victim", map[string]any{
394			"deviceId": "dev-1", "type": "counter",
395			"ops": []any{crdtCounterOp("op-1", 1)},
396		}); code != http.StatusOK {
397			t.Fatalf("victim crdt = %d", code)
398		}
399		if code := postCRDTOps(t, srv, "other", map[string]any{
400			"deviceId": "dev-2", "type": "counter",
401			"ops": []any{crdtCounterOp("op-1", 1)},
402		}); code != http.StatusOK {
403			t.Fatalf("other crdt = %d", code)
404		}
405	
406		// Four connections on the victim: document- and session-level for each
407		// channel.
408		victimChangeDoc, _ := dialWS(t, docSubscribeURL(srv, "victim", "dev-1", "0"))
409		if victimChangeDoc == nil {
410			t.Fatal("victim doc change subscription did not upgrade")
411		}
412		defer victimChangeDoc.close()
413		victimChangeSess, _ := dialWS(t, subscribeURL(srv, "sess-1", "victim", "0"))
414		if victimChangeSess == nil {
415			t.Fatal("victim session change subscription did not upgrade")
416		}
417		defer victimChangeSess.close()
418		victimStateDoc, _ := dialWS(t, docCRDTSubscribeURL(srv, "victim", "dev-1"))
419		if victimStateDoc == nil {
420			t.Fatal("victim doc state subscription did not upgrade")
421		}
422		defer victimStateDoc.close()
423		victimStateSess, _ := dialWS(t, crdtSubscribeURL(srv, "sess-1", "victim"))
424		if victimStateSess == nil {
425			t.Fatal("victim session state subscription did not upgrade")
426		}
427		defer victimStateSess.close()
428	
429		// Two control connections on another document.
430		controlChange, _ := dialWS(t, docSubscribeURL(srv, "other", "dev-2", "0"))
431		if controlChange == nil {
432			t.Fatal("control change subscription did not upgrade")
433		}
434		defer controlChange.close()
435		controlState, _ := dialWS(t, docCRDTSubscribeURL(srv, "other", "dev-2"))
436		if controlState == nil {
437			t.Fatal("control state subscription did not upgrade")
438		}
439		defer controlState.close()
440	
441		waitForSubscriptionCount(t, srv, "dev-1", 4) // all four victim connections
442		waitForSubscriptionCount(t, srv, "dev-2", 2) // control change+state are dev-2's
443	
444		// The state subscriptions push the current merge first; drain so the close
445		// frame is the next thing read.
446		if state := victimStateDoc.readCRDTState(); state.Type != "counter" {
447			t.Fatalf("victim state = %v", state)
448		}
449		if state := victimStateSess.readCRDTState(); state.Type != "counter" {
450			t.Fatalf("victim session state = %v", state)
451		}
452		if state := controlState.readCRDTState(); state.Type != "counter" {
453			t.Fatalf("control state = %v", state)
454		}
455		// The change subscriptions replay the one seeded victim change / nothing
456		// for the empty control doc.
457		if row := victimChangeDoc.readChange(); row.ID != "seed-1" {
458			t.Fatalf("victim replay = %q", row.ID)
459		}
460		if row := victimChangeSess.readChange(); row.ID != "seed-1" {
461			t.Fatalf("victim session replay = %q", row.ID)
462		}
463	
464		if status, _, body := deleteDocument(t, srv, "victim", "dev-1"); status != http.StatusOK {
465			t.Fatalf("delete = %d %s", status, body)
466		}
467	
468		// Every victim connection ends 4420 on both channels and both identity
469		// flows.
470		for name, c := range map[string]*wsClient{
471			"doc change":     victimChangeDoc,
472			"session change": victimChangeSess,
473			"doc state":      victimStateDoc,
474			"session state":  victimStateSess,
475		} {
476			c.setReadDeadline(2 * time.Second)
477			if code := c.readCloseCode(); code != 4420 {
478				t.Fatalf("%s subscription close code = %d, want 4420", name, code)
479			}
480			c.clearReadDeadline()
481		}
482	
483		// The victim's entries vanish from both devices' management lists.
484		if got := waitForSubscriptionCount(t, srv, "dev-1", 0); len(got) != 0 {
485			t.Fatalf("victim subscriptions still listed for dev-1: %+v", got)
486		}
487	
488		// The control document keeps pushing on both channels.
489		postDocChange(t, srv, "dev-2", "other", "after-delete", map[string]any{"n": 9})
490		if row := controlChange.readChange(); row.ID != "after-delete" {
491			t.Fatalf("control change subscriber got %q, want the live commit", row.ID)
492		}
493		if code := postCRDTOps(t, srv, "other", map[string]any{
494			"deviceId": "dev-2", "type": "counter",
495			"ops": []any{crdtCounterOp("op-2", 4)},
496		}); code != http.StatusOK {
497			t.Fatalf("control crdt op = %d", code)
498		}
499		state := controlState.readCRDTState()
500		if n := crdtCounterValue(t, state); n != 4 {
501			t.Fatalf("control state after delete = %d, want 4 (per-device max)", n)
502		}
503	
504		// Control connections stay open: no frame arrives unsolicited.
505		controlChange.setReadDeadline(300 * time.Millisecond)
506		if _, _, _, ok := controlChange.readFrameMaybe(); ok {
507			t.Fatal("control change connection was disturbed by the deletion")
508		}
509		controlChange.clearReadDeadline()
510	}
511	
512	// A long poll parked on the document returns at once when the document is
513	// deleted, answering as an unknown document (empty list, cursor 0, not timed
514	// out) rather than holding until its deadline.
515	func TestDeleteDocumentWakesParkedPoll(t *testing.T) {
516		srv, _ := newWSTestServer(t)
517		registerDeviceViaHTTP(t, srv, "dev-1")
518		postDocChange(t, srv, "dev-1", "doc", "c1", map[string]any{"n": 1})
519	
520		type pollResult struct {
521			status int
522			body   string
523		}
524		done := make(chan pollResult, 1)
525		go func() {
526			req, _ := http.NewRequest(http.MethodGet,
527				srv.URL+"/v1/documents/doc/changes/poll?after=1&limit=100&waitMs=10000", nil)
528			resp, err := srv.Client().Do(req)
529			if err != nil {
530				done <- pollResult{0, err.Error()}
531				return
532			}
533			defer resp.Body.Close()
534			buf := make([]byte, 4096)
535			n, _ := resp.Body.Read(buf)
536			done <- pollResult{resp.StatusCode, string(buf[:n])}
537		}()
538	
539		// Give the poll time to park, then delete.
540		time.Sleep(200 * time.Millisecond)
541		if status, _, body := deleteDocument(t, srv, "doc", "dev-1"); status != http.StatusOK {
542			t.Fatalf("delete = %d %s", status, body)
543		}
544	
545		select {
546		case got := <-done:
547			if got.status != http.StatusOK {
548				t.Fatalf("poll status = %d", got.status)
549			}
550			if !strings.Contains(got.body, `"timedOut":false`) ||
551				!strings.Contains(got.body, `"nextCursor":0`) ||
552				!strings.Contains(got.body, `"changes":[]`) {
553				t.Fatalf("parked poll after delete = %q", got.body)
554			}
555		case <-time.After(2 * time.Second):
556			t.Fatal("parked poll was not woken by the document deletion")
557		}
558	}
559	
560	// The deletion is durable: after a process restart a repeat delete still
561	// misses (404), the reads stay those of an unknown document, and the verdict
562	// is unchanged.
563	func TestDeleteDocumentPersistsAcrossRestart(t *testing.T) {
564		path := filepath.Join(t.TempDir(), "doc-delete-restart.db")
565	
566		s, err := app.Open(path)
567		if err != nil {
568			t.Fatal(err)
569		}
570		h := NewHandler(s)
571		srv := httptest.NewServer(h)
572		registerDevice(t, h, "dev-1")
573		postDocChangeHandler(t, h, "dev-1", "doc")
574		if code := postHTTP(t, srv, "/v1/documents/doc/crdt/ops", map[string]any{
575			"deviceId": "dev-1", "type": "counter",
576			"ops": []any{crdtCounterOp("op-1", 3)},
577		}); code != http.StatusOK {
578			t.Fatalf("crdt = %d", code)
579		}
580		w, _ := doRequest(t, h, http.MethodDelete, "/v1/documents/doc?deviceId=dev-1")
581		if w.Code != http.StatusOK {
582			t.Fatalf("delete = %d", w.Code)
583		}
584		srv.Close()
585		if err := s.Close(); err != nil {
586			t.Fatal(err)
587		}
588	
589		s2, err := app.Open(path)
590		if err != nil {
591			t.Fatal(err)
592		}
593		t.Cleanup(func() { _ = s2.Close() })
594		h2 := NewHandler(s2)
595	
596		// Repeat delete after restart: still 404, zero writes.
597		w, _ = doRequest(t, h2, http.MethodDelete, "/v1/documents/doc?deviceId=dev-1")
598		if w.Code != http.StatusNotFound {
599			t.Fatalf("repeat delete after restart = %d, want 404", w.Code)
600		}
601		// Changes and CRDT state stay gone.
602		w, _ = doRequest(t, h2, http.MethodGet, "/v1/documents/doc/changes")
603		if strings.TrimSpace(w.Body.String()) != `{"changes":[],"nextCursor":0}` {
604			t.Fatalf("changes after restart = %s", w.Body.String())
605		}
606		w, _ = doRequest(t, h2, http.MethodGet, "/v1/documents/doc/crdt/state")
607		if w.Code != http.StatusNotFound {
608			t.Fatalf("crdt state after restart = %d, want 404", w.Code)
609		}
610	
611		// The re-created document starts fresh with cursor 1.
612		postDocChangeHandler(t, h2, "dev-1", "doc")
613		w, _ = doRequest(t, h2, http.MethodGet, "/v1/documents/doc/changes")
614		var page struct {
615			Changes []struct {
616				Cursor float64 `json:"cursor"`
617			} `json:"changes"`
618		}
619		if err := json.Unmarshal(w.Body.Bytes(), &page); err != nil || len(page.Changes) != 1 || page.Changes[0].Cursor != 1 {
620			t.Fatalf("fresh cursor after restart: %s", w.Body.String())
621		}
622	}
