		// adds one trailing "subscribe" segment and keeps its own endpoint.
		// Anything else (a trailing slash, an unrecognized extra segment) is a
		// malformed 400.
		if i == 1 {
			collection := len(segs) == 2 && segs[0] != ""
			knownSubresource := len(segs) >= 3 &&
				(segs[2] == "poll" || segs[2] == "compact" || segs[2] == "subscribe")
			return !(collection || knownSubresource)
		}
		return false
	}
	return false
}
func malformedCRDTPath(p string) bool {
	rest, ok := strings.CutPrefix(p, "/v1/documents/")
	if !ok {
		return false
	}
	segs := strings.Split(rest, "/")
	for i, seg := range segs {
		if seg == "crdt" && i > 0 {
			if segs[0] == "" {
				return true
			}
			// The CRDT state subscription adds one trailing "subscribe"
			// segment past the state read; nothing else may follow state.
			if len(segs) == 4 && segs[2] == "state" && segs[3] == "subscribe" {
				return false
			}
			if len(segs) != 3 {
				return true
			}
			switch segs[2] {
			case "ops", "state", "compact", "snapshot":
				return false
			default:
				return true
			}
		}
	}
	return false
}
func malformedPermissionPath(p string) bool {
	rest, ok := strings.CutPrefix(p, "/v1/documents/")
	if !ok {
		return false
	}
	segs := strings.Split(rest, "/")
	for i, seg := range segs {
		if seg != "permissions" {
			continue
		}
		if i == 0 {
			// The keyword sits where the document id belongs. Bare, or with a
			// trailing slash, the documentID segment is missing; with a real
			// suffix it is an ordinary document named "permissions", so keep
			// scanning for the keyword in its resource position.
			if len(segs) == 1 || (len(segs) == 2 && segs[1] == "") {
				return true
			}
			continue
		}
		// Keyword position reached. The resource is exactly
		// {documentID}/permissions; a trailing slash or any further segment is
		// malformed.
		valid := len(segs) == 2 && segs[0] != ""
		return !valid
	}
	return false
}

