// handlePutSnapshotVersion registers an existing snapshot under a stable
// version name:
//
//	POST /v1/documents/{documentID}/snapshots/versions
//
// The name is unique within the document. Binding the same name to the same
// cursor again is idempotent and returns the identical body; binding that name
// to another cursor (or a name another cursor occupies) is a 409 with zero
// writes. The fixed verdict order is request shape (400), device existence
// (404), document permission (403), then snapshot and version existence (404)
// and the conflict verdict (409). Success is one compact JSON line naming the
// version and the snapshot cursor.
func handlePutSnapshotVersion(s *app.App, w http.ResponseWriter, r *http.Request) {
	documentID := r.PathValue("documentID") // route pattern + guard guarantee non-empty

	deviceID, cursor, ok := decodeVersionBindRequest(w, r)
	if !ok {
		return
	}

	result, err := s.PutSnapshotVersion(documentID, deviceID, r.URL.Query().Get("name"), cursor)
	if err != nil {
		if !writeVersionGateError(w, err) {
			writeError(w, http.StatusInternalServerError, "failed to register snapshot version")
		}
		return
	}
	writeJSON(w, http.StatusOK, result)
}

