1	package events
2	
3	import (
4		"database/sql"
5		"encoding/json"
6		"errors"
7	)
8	
9	// PutSnapshotVersion binds an existing snapshot of documentID to the stable
10	// version name, all inside one serialized transaction.
11	//
12	// The gate (registration then permission) is taken first in the transaction:
13	// an unregistered device yields store.ErrDeviceNotFound and a revoked device
14	// store.ErrPermissionDenied, before any snapshot or version is observed. Then
15	// the target snapshot must exist (a miss, an unknown document included, is
16	// ErrSnapshotNotFound), and finally the name is resolved:
17	//
18	//   - an unbound name is inserted and reports the binding;
19	//   - a name already bound to the same cursor is idempotent and reports the
20	//     very same name/cursor pair (the HTTP body is byte-identical to the first
21	//     registration);
22	//   - a name already bound to another cursor is *ErrVersionConflict with zero
23	//     writes.
24	//
25	// A version marker never copies or moves snapshot bytes and creates no
26	// change.
27	func (s *Service) PutSnapshotVersion(documentID, deviceID, name string, cursor int64) (VersionResult, error) {
28		tx, err := s.db.Begin()
29		if err != nil {
30			return VersionResult{}, err
31		}
32		defer func() { _ = tx.Rollback() }()
33	
34		if err := gateTx(s, tx, documentID, deviceID); err != nil {
35			return VersionResult{}, err
36		}
37		if err := snapshotExistsTx(tx, documentID, cursor); err != nil {
38			return VersionResult{}, err
39		}
40	
41		var existing sql.NullInt64
42		err = tx.QueryRow(
43			`SELECT cursor FROM snapshot_versions WHERE document_id = ? AND name = ?`,
44			documentID, name,
45		).Scan(&existing)
46		switch {
47		case errors.Is(err, sql.ErrNoRows):
48			// An unbound name: insert below.
49		case err != nil:
50			return VersionResult{}, err
51		case existing.Int64 != cursor:
52			return VersionResult{}, &ErrVersionConflict{Name: name}
53		default:
54			// Already bound to the same cursor: idempotent, zero writes.
55			if err := tx.Commit(); err != nil {
56				return VersionResult{}, err
57			}
58			return VersionResult{Name: name, Cursor: cursor}, nil
59		}
60		if _, err := tx.Exec(
61			`INSERT INTO snapshot_versions (document_id, name, cursor) VALUES (?, ?, ?)`,
62			documentID, name, cursor,
63		); err != nil {
64			return VersionResult{}, err
65		}
66		if err := tx.Commit(); err != nil {
67			return VersionResult{}, err
68		}
69		return VersionResult{Name: name, Cursor: cursor}, nil
70	}
71	
72	// ListSnapshotVersions returns every version marker of documentID in
73	// ascending name order, together with the snapshot cursor each points at. The
74	// gate runs first in the transaction (404 for an unregistered device, 403 for
75	// a revoked one); an unknown document or a document without markers then
76	// reads as an empty list rather than an error. It writes nothing.
77	func (s *Service) ListSnapshotVersions(documentID, deviceID string) ([]SnapshotVersion, error) {
78		tx, err := s.db.Begin()
79		if err != nil {
80			return nil, err
81		}
82		defer func() { _ = tx.Rollback() }()
83	
84		if err := gateTx(s, tx, documentID, deviceID); err != nil {
85			return nil, err
86		}
87	
88		rows, err := tx.Query(
89			`SELECT name, cursor FROM snapshot_versions
90			 WHERE document_id = ? ORDER BY name ASC`,
91			documentID,
92		)
93		if err != nil {
94			return nil, err
95		}
96		defer func() { _ = rows.Close() }()
97	
98		out := make([]SnapshotVersion, 0)
99		for rows.Next() {
100			var v SnapshotVersion
101			if err := rows.Scan(&v.Name, &v.Cursor); err != nil {
102				return nil, err
103			}
104			out = append(out, v)
105		}
106		if err := rows.Err(); err != nil {
107			return nil, err
108		}
109		return out, tx.Commit()
110	}
111	
112	// GetSnapshotVersionState resolves a version name to its snapshot and returns
113	// that snapshot's cursor and stored state, exactly as GetSnapshot would for
114	// the cursor. The gate runs first; a name without a marker is
115	// ErrVersionNotFound and a marker whose snapshot is gone is
116	// ErrSnapshotNotFound — the caller maps both to 404 and exposes no content.
117	func (s *Service) GetSnapshotVersionState(documentID, deviceID, name string) (int64, json.RawMessage, error) {
118		tx, err := s.db.Begin()
119		if err != nil {
120			return 0, nil, err
121		}
122		defer func() { _ = tx.Rollback() }()
123	
124		if err := gateTx(s, tx, documentID, deviceID); err != nil {
125			return 0, nil, err
126		}
127	
128		var cursor int64
129		err = tx.QueryRow(
130			`SELECT cursor FROM snapshot_versions WHERE document_id = ? AND name = ?`,
131			documentID, name,
132		).Scan(&cursor)
133		switch {
134		case errors.Is(err, sql.ErrNoRows):
135			return 0, nil, ErrVersionNotFound
136		case err != nil:
137			return 0, nil, err
138		}
139	
140		var state []byte
141		if err := tx.QueryRow(
142			`SELECT state FROM snapshots WHERE document_id = ? AND cursor = ?`,
143			documentID, cursor,
144		).Scan(&state); err != nil {
145			if errors.Is(err, sql.ErrNoRows) {
146				return 0, nil, ErrSnapshotNotFound
147			}
148			return 0, nil, err
149		}
150		return cursor, json.RawMessage(state), tx.Commit()
151	}
152	
153	// RebindSnapshotVersion moves an existing version name of documentID to
154	// another existing snapshot cursor in one serialized transaction. The gate
155	// (404/403) is taken first; the named marker must exist (ErrVersionNotFound)
156	// and the target snapshot must exist (ErrSnapshotNotFound, an unknown
157	// document included). Rebinding to the cursor already bound is an idempotent
158	// no-op reporting the same pair; otherwise the marker is updated. The
159	// snapshot itself is never modified or copied.
160	func (s *Service) RebindSnapshotVersion(documentID, deviceID, name string, cursor int64) (VersionResult, error) {
161		tx, err := s.db.Begin()
162		if err != nil {
163			return VersionResult{}, err
164		}
165		defer func() { _ = tx.Rollback() }()
166	
167		if err := gateTx(s, tx, documentID, deviceID); err != nil {
168			return VersionResult{}, err
169		}
170	
171		var existing int64
172		err = tx.QueryRow(
173			`SELECT cursor FROM snapshot_versions WHERE document_id = ? AND name = ?`,
174			documentID, name,
175		).Scan(&existing)
176		switch {
177		case errors.Is(err, sql.ErrNoRows):
178			return VersionResult{}, ErrVersionNotFound
179		case err != nil:
180			return VersionResult{}, err
181		}
182		if err := snapshotExistsTx(tx, documentID, cursor); err != nil {
183			return VersionResult{}, err
184		}
185		if existing != cursor {
186			if _, err := tx.Exec(
187				`UPDATE snapshot_versions SET cursor = ? WHERE document_id = ? AND name = ?`,
188				cursor, documentID, name,
189			); err != nil {
190				return VersionResult{}, err
191			}
192		}
193		if err := tx.Commit(); err != nil {
194			return VersionResult{}, err
195		}
196		return VersionResult{Name: name, Cursor: cursor}, nil
197	}
198	
199	// DeleteSnapshotVersion hard-deletes one version marker of documentID. The
200	// gate (404/403) is taken first; a name without a marker is
201	// ErrVersionNotFound. The snapshot is left untouched; once the marker commits
202	// the name is free to bind again.
203	func (s *Service) DeleteSnapshotVersion(documentID, deviceID, name string) error {
204		tx, err := s.db.Begin()
205		if err != nil {
206			return err
207		}
208		defer func() { _ = tx.Rollback() }()
209	
210		if err := gateTx(s, tx, documentID, deviceID); err != nil {
211			return err
212		}
213	
214		var bound int64
215		if err := tx.QueryRow(
216			`SELECT cursor FROM snapshot_versions WHERE document_id = ? AND name = ?`,
217			documentID, name,
218		).Scan(&bound); err != nil {
219			if errors.Is(err, sql.ErrNoRows) {
220				return ErrVersionNotFound
221			}
222			return err
223		}
224		if _, err := tx.Exec(
225			`DELETE FROM snapshot_versions WHERE document_id = ? AND name = ?`,
226			documentID, name,
227		); err != nil {
228			return err
229		}
230		return tx.Commit()
231	}
232	
233	// RestoreSnapshotVersion resolves a version name of documentID to its
234	// snapshot and appends that snapshot's state as one ordinary change, with
235	// exactly the semantics of RestoreSnapshot: the gate is taken first in the
236	// transaction, a missing marker yields ErrVersionNotFound and a missing
237	// snapshot ErrSnapshotNotFound, after which the shared restore path decides
238	// idempotency and conflict (an id occupied by an ordinary change is 409). The
239	// document cursor advances by one on a genuinely new restore and the long
240	// polls and subscribers are woken.
241	func (s *Service) RestoreSnapshotVersion(documentID, deviceID, changeID, name string) (RestoreResult, error) {
242		tx, err := s.db.Begin()
243		if err != nil {
244			return RestoreResult{}, err
245		}
246		defer func() { _ = tx.Rollback() }()
247	
248		if err := gateTx(s, tx, documentID, deviceID); err != nil {
249			return RestoreResult{}, err
250		}
251	
252		var snapshotCursor int64
253		err = tx.QueryRow(
254			`SELECT cursor FROM snapshot_versions WHERE document_id = ? AND name = ?`,
255			documentID, name,
256		).Scan(&snapshotCursor)
257		switch {
258		case errors.Is(err, sql.ErrNoRows):
259			return RestoreResult{}, ErrVersionNotFound
260		case err != nil:
261			return RestoreResult{}, err
262		}
263	
264		result, err := restoreSnapshotTx(tx, documentID, deviceID, changeID, snapshotCursor)
265		if err != nil {
266			return RestoreResult{}, err
267		}
268		if err := tx.Commit(); err != nil {
269			return RestoreResult{}, err
270		}
271		if result.Created {
272			s.notifyWaiters(documentID)
273		}
274		return result, nil
275	}
276	
277	// gateTx runs the service's registration/permission gate inside tx. A service
278	// built without a gate (some service-level tests) skips the verdict.
279	func gateTx(s *Service, tx *sql.Tx, documentID, deviceID string) error {
280		if s.gate == nil {
281			return nil
282		}
283		return s.gate.DeviceAuthorizedTx(tx, documentID, deviceID)
284	}
285	
286	// snapshotExistsTx reports whether documentID has a snapshot at cursor,
287	// returning ErrSnapshotNotFound on a miss. It runs inside the caller's
288	// serialized transaction so the existence verdict and the following write are
289	// one judgment.
290	func snapshotExistsTx(tx *sql.Tx, documentID string, cursor int64) error {
291		var state []byte
292		if err := tx.QueryRow(
293			`SELECT state FROM snapshots WHERE document_id = ? AND cursor = ?`,
294			documentID, cursor,
295		).Scan(&state); err != nil {
296			if errors.Is(err, sql.ErrNoRows) {
297				return ErrSnapshotNotFound
298			}
299			return err
300		}
301		return nil
302	}
